import { describe, expect, it } from 'vitest';
import {
  columnTrack,
  computeSelectionUnits,
  couchState,
  isAccessible,
  priceForRow,
  seatId,
  seatState,
  unitPrice,
  unitSeatLabel,
} from './seat-geometry';
import { resolveSelectedDate, upcomingDayOptions, formatShowDate, todayISO } from './date';
import {
  validateConfirmEmail,
  validateEmail,
  validateFirstName,
  validatePhone,
} from './validation';

describe('seat geometry counts', () => {
  it('has 308 selectable elements total', () => {
    let seats = 0;
    let couches = 0;
    for (let row = 1; row <= 15; row++) {
      if (row === 15) {
        couches += 12;
        continue;
      }
      const columns = row <= 10 ? 20 : 24;
      seats += columns;
    }
    expect(seats).toBe(296);
    expect(couches).toBe(12);
    expect(seats + couches).toBe(308);
  });

  it('marks row 1 columns 10-15 as accessible, nothing else', () => {
    let count = 0;
    for (let c = 5; c <= 24; c++) {
      if (isAccessible(1, c)) count++;
    }
    expect(count).toBe(6);
    expect(isAccessible(2, 12)).toBe(false);
  });

  it('maps columns to grid tracks without overlapping the aisles', () => {
    expect(columnTrack(4)).toBe(5);
    expect(columnTrack(5)).toBe(7);
    expect(columnTrack(20)).toBe(22);
    expect(columnTrack(21)).toBe(24);
  });

  it('prices rows correctly', () => {
    expect(priceForRow(1)).toBe(25);
    expect(priceForRow(5)).toBe(25);
    expect(priceForRow(6)).toBe(32);
    expect(priceForRow(10)).toBe(32);
    expect(priceForRow(11)).toBe(39);
    expect(priceForRow(14)).toBe(39);
    expect(priceForRow(15)).toBe(89);
  });

  it('computes couch state as unavailable if either half is occupied', () => {
    const occupied = new Set(['R15C5']);
    expect(couchState(15, 5, occupied, new Set())).toBe('unavailable');
    expect(couchState(15, 7, occupied, new Set())).toBe('available');
  });

  it('groups selected seats into units ordered by row then column', () => {
    const seats = [seatId(7, 12), seatId(7, 11), seatId(15, 3), seatId(15, 4)];
    const units = computeSelectionUnits(seats);
    expect(units).toHaveLength(3);
    expect(units[0]).toMatchObject({ row: 7, columns: [11] });
    expect(units[1]).toMatchObject({ row: 7, columns: [12] });
    expect(units[2]).toMatchObject({ row: 15, isCouch: true, columns: [3, 4] });
    expect(unitPrice(units[2])).toBe(89);
    expect(unitSeatLabel(units[2])).toBe('3-4');
  });

  it('seatState reports accessible only when free and unselected', () => {
    expect(seatState(1, 12, new Set(), new Set())).toBe('accessible');
    expect(seatState(1, 12, new Set(['R1C12']), new Set())).toBe('unavailable');
    expect(seatState(1, 12, new Set(), new Set(['R1C12']))).toBe('selected');
  });
});

describe('date helpers', () => {
  it('resolves missing/invalid/past dates to today', () => {
    const today = todayISO();
    expect(resolveSelectedDate(null)).toBe(today);
    expect(resolveSelectedDate('not-a-date')).toBe(today);
    expect(resolveSelectedDate('2000-01-01')).toBe(today);
  });

  it('builds 5 day options starting with Today', () => {
    const options = upcomingDayOptions();
    expect(options).toHaveLength(5);
    expect(options[0].label).toBe('Today');
  });

  it('formats the show date as specified', () => {
    expect(formatShowDate('2026-09-15', '16:00')).toBe('Tuesday 15 Sep 16:00');
  });
});

describe('validation', () => {
  it('validates email format per spec examples', () => {
    expect(validateEmail('anna@example.com')).toBeNull();
    expect(validateEmail('not-an-email')).not.toBeNull();
    expect(validateEmail('a@b')).not.toBeNull();
    expect(validateEmail('a@.com')).not.toBeNull();
  });

  it('requires confirm email to match exactly', () => {
    expect(validateConfirmEmail('a@b.com', 'a@b.com')).toBeNull();
    expect(validateConfirmEmail('a@b.com', 'a@b.co')).not.toBeNull();
    expect(validateConfirmEmail('a@b.com', '')).not.toBeNull();
  });

  it('requires first name at least 2 characters', () => {
    expect(validateFirstName('')).toBe('First name is required');
    expect(validateFirstName('A')).toBe('First name must be at least 2 characters');
    expect(validateFirstName('Al')).toBeNull();
  });

  it('phone is optional but exactly 9 digits when filled', () => {
    expect(validatePhone('')).toBeNull();
    expect(validatePhone('12345678')).not.toBeNull();
    expect(validatePhone('123456789')).toBeNull();
  });
});

