  it('has 308 selectable elements total', () => {
    let seats = 0;
    let couches = 0;
    for (let row = 1; row <= 15; row++) {
      if (row === 15) {
        couches += 12;
        continue;
      }
      const columns = row <= 10 ? 20 : 24;
      seats += columns;
    }
    expect(seats).toBe(296);
    expect(couches).toBe(12);
    expect(seats + couches).toBe(308);
  });

  it('marks row 1 columns 10-15 as accessible, nothing else', () => {
    let count = 0;
    for (let c = 5; c <= 24; c++) {
      if (isAccessible(1, c)) count++;
    }
    expect(count).toBe(6);
    expect(isAccessible(2, 12)).toBe(false);
  });

  it('maps columns to grid tracks without overlapping the aisles', () => {
    expect(columnTrack(4)).toBe(5);
    expect(columnTrack(5)).toBe(7);
